(()=>{'use strict';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data={},busy=false;const date=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),5000)}function fail(e){toast(e.message)}const open=h=>{$('#dialog-content').innerHTML=h;$('#dialog').showModal()},close=()=>$('#dialog').close();$('#close-dialog').onclick=close;
async function load(){if(!MM.session){auth();return}try{data=await MM.api({action:'list'});render()}catch(e){fail(e);$('#main').innerHTML='<section class="card"><h2>Could not load live operations.</h2><p>Refresh to retry. This view never substitutes sample jobs.</p></section>';}}
function auth(){$('#main').innerHTML=`<section class="card auth"><p class="eyebrow">CONNECTED FIELD OPERATIONS</p><h1>Office and Crew.<br>Working together.</h1><p>Sign in with your Mow Matter account to create your business, assign crew members and track real job activity.</p><form id="auth" class="form"><label>Email<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" minlength="8" required autocomplete="current-password"></label><p id="auth-status" role="status"></p><div class="actions"><button class="button primary" value="login">Sign in</button><button class="button" value="signup">Create account</button></div></form><p class="help">Confirm your email after signing up, then return to sign in. Crew members use the same account in the Crew app.</p></section>`;$('#auth').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.submitter;b.disabled=true;try{if(b.value==='signup'){await MM.signUp(f.get('email'),f.get('password'));$('#auth-status').textContent='Check your email to confirm, then return here to sign in.'}else{await MM.signIn(f.get('email'),f.get('password'));await load()}}catch(err){$('#auth-status').textContent=err.message}finally{b.disabled=false}};}
function render(){if(!data.company){$('#main').innerHTML=`<section class="card auth"><h1>Make it your business.</h1><p>Your account is ready. Create your business workspace to begin assigning jobs.</p><form id="business" class="form"><label>Business name<input name="name" minlength="2" maxlength="120" required placeholder="Your lawn care company"></label><button class="button primary full">Create my workspace</button></form><p class="help">Crew member? Your owner assigns your confirmed email from their workspace.</p></section>`;$('#business').onsubmit=async e=>{e.preventDefault();try{await MM.api({action:'bootstrap',name:new FormData(e.target).get('name')});await load()}catch(err){fail(err)}};return}
const owner=data.profile.role==='owner',jobs=data.jobs,done=jobs.filter(j=>j.status==='completed').length;
$('#main').innerHTML=`<div class="page-head"><div><p class="eyebrow">${esc(data.company.name)} · LIVE DATA</p><h1>Keep the field moving.</h1></div>${owner?'<div class="actions"><button id="property-tools" class="button">Property quote</button><button id="new-job" class="button primary">+ Assign job</button></div>':''}</div><div class="demo-bar">Connected Supabase workspace · Your actual assigned records. The sample overview and valuation remain separate.</div><div class="stats"><div><strong>${jobs.length}</strong><span>Assigned jobs</span></div><div><strong>${done}</strong><span>Completed</span></div><div><strong>${data.members.length}</strong><span>Team members</span></div></div><div class="split"><section class="card"><h2>Field activity</h2><ul class="job-list">${jobs.map(j=>`<li><div style="flex:1"><b>${esc(j.address)}</b><small>${esc(j.customer_name)} · ${esc(j.service_date)} · ${esc(data.members.find(m=>m.user_id===j.assigned_to)?.display_name||'Assigned crew')}</small></div><span class="pill ${esc(j.status)}">${esc(j.status.replaceAll('_',' '))}</span><button class="button" data-job="${j.id}">Details</button></li>`).join('')||'<li>No jobs yet. Assign your first lawn to see Crew activity here.</li>'}</ul></section><section class="card"><h2>Your team</h2>${data.members.map(m=>`<p><b>${esc(m.display_name)}</b> <span class="pill">${esc(m.role)}</span></p>`).join('')}${owner?'<button class="button full" id="assign">Assign confirmed crew account</button>':''}<p class="help" style="margin-top:12px">Crew members create and confirm their accounts first. Adding their email grants access only to this business and their assigned jobs.</p><h3 style="margin-top:24px">Homeowner delivery</h3><p class="help">Start and completion updates are saved automatically. SMS/email delivery needs a messaging provider; these records are not marked as sent.</p></section></div><section class="card"><h2>Team messages</h2>${data.messages.slice().reverse().map(m=>`<div class="message"><small>${esc(data.members.find(u=>u.user_id===m.actor_id)?.display_name||'Team')} · ${esc(new Date(m.created_at).toLocaleString())}</small>${esc(m.body)}</div>`).join('')||'<p>No messages yet.</p>'}<form id="message" class="form"><label>Message to crew<textarea name="text" required maxlength="2000"></textarea></label><button class="button primary">Send team message</button></form></section>`;
if(owner){$('#property-tools').onclick=()=>window.openPropertyTools();$('#new-job').onclick=createJob;$('#assign').onclick=assign}document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>details(jobs.find(j=>j.id===b.dataset.job)));$('#message').onsubmit=async e=>{e.preventDefault();try{await MM.api({action:'message',text:new FormData(e.target).get('text')});await load()}catch(err){fail(err)}};}
function createJob(){open(`<h2>Assign the next lawn.</h2><form id="job-form" class="form"><label>Customer name<input name="customer_name" required maxlength="100"></label><label>Street address<input name="address" required maxlength="200"></label><label>City and state<input name="city" value="Palm Coast, FL" required></label><label>Service date<input type="date" name="service_date" value="${date()}" required></label><label>Start time<input type="time" name="scheduled_time" value="09:00" required></label><label>Crew member<select name="assigned_to">${data.members.map(m=>`<option value="${m.user_id}">${esc(m.display_name)}</option>`).join('')}</select></label><div class="checklist">${['Mow','Edge','Trim','Blow','Cleanup'].map(s=>`<label><input type="checkbox" name="services" value="${s}" ${['Mow','Edge','Blow'].includes(s)?'checked':''}>${s}</label>`).join('')}</div><label>Access notes<textarea name="notes" maxlength="1500" placeholder="Gate access, pets, special instructions"></textarea></label><label>Latitude (optional)<input type="number" name="latitude" step="any" min="-90" max="90"></label><label>Longitude (optional)<input type="number" name="longitude" step="any" min="-180" max="180"></label><p class="help">Add verified property coordinates for location prompts. Leave blank for manual check-in. Geocoding is not connected yet.</p><label>Customer email (optional)<input type="email" name="customer_email"></label><label>Customer phone (optional)<input type="tel" name="customer_phone"></label><label class="check"><input type="checkbox" name="requires_photo" checked>Require completion photo</label><label class="check"><input type="checkbox" name="notification_consent">Customer has agreed to service notifications</label><p class="help">Notifications are queued only. No SMS/email provider is connected.</p><button class="button primary full">Create assigned job</button></form>`);$('#job-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),j=Object.fromEntries(f);j.services=f.getAll('services');j.requires_photo=f.has('requires_photo');j.notification_consent=f.has('notification_consent');e.submitter.disabled=true;try{await MM.api({action:'create_job',job:j});close();await load();toast('Job assigned. Crew sees it on refresh.')}catch(err){fail(err);e.submitter.disabled=false}};}
function assign(){open('<h2>Connect a crew account.</h2><form id="assign-form" class="form"><label>Confirmed account email<input name="email" type="email" required></label><label>Crew display name<input name="name" maxlength="80" required></label><button class="button primary full">Add crew member</button></form>');$('#assign-form').onsubmit=async e=>{e.preventDefault();try{await MM.api({action:'assign_member',...Object.fromEntries(new FormData(e.target))});close();await load()}catch(err){fail(err)}};}
function details(j){open(`<h2>${esc(j.address)}</h2><p>${esc(j.customer_name)} · ${esc(j.status.replaceAll('_',' '))}</p><p>${esc(j.notes)}</p><h3>Job timeline</h3><ul class="timeline">${data.events.filter(e=>e.job_id===j.id).map(e=>`<li>${esc(e.action.replaceAll('_',' '))}<small>${esc(new Date(e.created_at).toLocaleString())}</small>${e.payload.location?`<small>Location captured ±${Math.round(e.payload.location.accuracy)} m</small>`:''}${e.payload.manual?`<small>Manual: ${esc(e.payload.manual_reason)}</small>`:''}${e.payload.reason?`<p>${esc(e.payload.reason)}</p>`:''}</li>`).join('')||'<li>No activity yet.</li>'}</ul><div class="photo-grid">${data.photos.filter(p=>p.job_id===j.id).map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Private completion proof"></a>`).join('')}</div><h3>Homeowner update records</h3>${data.notifications.filter(n=>n.job_id===j.id).map(n=>`<div class="message">${esc(n.body)}<small>${esc(n.status.replaceAll('_',' '))}</small></div>`).join('')||'<p>No homeowner update yet.</p>'}`);}
$('#refresh').onclick=load;$('#logout').onclick=async()=>{await MM.signOut();auth()};load();setInterval(()=>{if(MM.session&&!document.hidden&&!$('#dialog').open&&!$('#message textarea')?.value&&!busy){busy=true;load().finally(()=>busy=false)}},30000);
})();
